excels.excel:

IMPORT WITH SHEET=1, HEADER=true,
    MAPPING={"学号":"no","姓名":"name","性别":"sex","年龄":"age","出生日期":"birthday","班级":"className"},
    TRANSFORM={"name":toUpper(${name}),"sex":trans(${dict},${sex}),"birthday":dateFormat(${birthday},'yyyy-MM-dd')}


EXPORT WITH SHEET="值转换", HEADER=true,
    MAPPING={"a":"姓名","b":"性别","c":"年龄"},
    TRANSFORM={"a":toUpper(${a}),"b":trans(${dict},${b}),"c":add(${c},1)}
